    return (False, None)
if m < 3:
    # parts must be at least 3 to ensure nontrivial generalized behavior
    # (the seed used 5; parts=2 is too simple and changes core dynamics)
    return (False, None)  # invalid instance
if N < 1:
    return (False, None)

# Helper: count integers in [a,b] with given parity (0=even, 1=odd)
def count_parity_in_interval(a, b, parity):
    if a > b:
        return 0
    first = a if (a % 2) == parity else a + 1
    if first > b:
        return 0
    return 1 + (b - first) // 2

# Plateau parity: P_t = parity of (m^t - 1)/(m - 1) = sum_{i=0}^{t-1} m^i
# If m is odd, every term is odd -> parity is t mod 2. If m even, only the i=0 term contributes -> parity 1.
def plateau_parity(t, m):
    if m % 2 == 1:
        return t % 2
    else:
        return 1

total_odd = 0
# n=1 yields f=0 -> even; no contribution.
# Process blocks for t >= 1.
t = 1
pow_prev = 1  # m^(t-1)
pow_t = m     # m^t
# Iterate while there's any overlap of plateau or ramp with [1,N]
while True:
    # Plateau interval A_t = [2*m^{t-1}, m^t]
    A_start = 2 * pow_prev
    A_end = pow_t
    if A_start <= N:
        # intersect with [1,N]
        L_start = max(A_start, 1)
        L_end = min(A_end, N)
        if L_start <= L_end:
            length = L_end - L_start + 1
            P = plateau_parity(t, m)
            if P % 2 == 1:
                total_odd += length
    # Ramp interval B_t = (m^t, 2*m^t) i.e., integers from m^t+1 to 2*m^t-1
    B_start = pow_t + 1
    B_end = 2 * pow_t - 1
    if B_start <= N:
        R_start = max(B_start, 1)
        R_end = min(B_end, N)
        if R_start <= R_end:
            if m % 2 == 1:
                # Odd m: parity(f) on ramp equals parity(n) + t + 1 (mod 2)
                # Thus f is odd exactly when n has parity == t mod 2
                wanted_parity = t % 2
                total_odd += count_parity_in_interval(R_start, R_end, wanted_parity)
            else:
                # Even m: parity(f) on ramp equals parity(n) + 1, so odd when n is even.
                total_odd += count_parity_in_interval(R_start, R_end, 0)
    # Termination: if neither plateau nor ramp intervals intersect [1,N] for this and future t, break.
    # Future intervals grow; once current A_start > N and B_start > N, we can stop.
    if A_start > N and B_start > N:
        break
    # advance t
    t += 1
    pow_prev = pow_t
    pow_t = pow_t * m
    # Safety cap to avoid infinite loops in pathological cases
    if t > 1000:
        # something is wrong; abort
        return (False, None)
return (True, total_odd)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

